ALTER TABLE users ADD COLUMN is_super_admin boolean NOT NULL DEFAULT false;
UPDATE users SET is_super_admin=true WHERE role='OWNER';
ALTER TABLE branches ADD COLUMN catalog_policy text NOT NULL DEFAULT 'LOCAL' CHECK(catalog_policy IN ('LOCAL','SHARED_ONLY'));
ALTER TABLE branches ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE branches ADD COLUMN registration_number text NOT NULL DEFAULT '';
ALTER TABLE branches ADD COLUMN tax_identifier text NOT NULL DEFAULT '';
CREATE TABLE branch_grants(user_id uuid NOT NULL REFERENCES users,branch_id uuid NOT NULL REFERENCES branches,role text NOT NULL CHECK(role IN ('OWNER','MANAGER','PHARMACIST','CASHIER','CLERK','ACCOUNTANT','AUDITOR')),PRIMARY KEY(user_id,branch_id));
INSERT INTO branch_grants(user_id,branch_id,role) SELECT id,branch_id,role FROM users;
CREATE FUNCTION initial_branch_grant() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO branch_grants(user_id,branch_id,role) VALUES(NEW.id,NEW.branch_id,NEW.role);RETURN NEW; END $$;
CREATE TRIGGER initial_branch_access AFTER INSERT ON users FOR EACH ROW EXECUTE FUNCTION initial_branch_grant();
ALTER TABLE sessions ADD COLUMN branch_id uuid REFERENCES branches;
UPDATE sessions s SET branch_id=u.branch_id FROM users u WHERE u.id=s.user_id;
CREATE TABLE shared_products(id uuid PRIMARY KEY,barcode text UNIQUE NOT NULL,name text NOT NULL,generic text NOT NULL,strength text NOT NULL,form text NOT NULL,manufacturer text NOT NULL,base_unit text NOT NULL,restricted boolean NOT NULL,units jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE medicines ADD COLUMN catalog_id uuid REFERENCES shared_products;
INSERT INTO shared_products(id,barcode,name,generic,strength,form,manufacturer,base_unit,restricted,units) SELECT m.id,m.barcode,m.name,m.generic,m.strength,m.form,m.manufacturer,m.base_unit,m.restricted,COALESCE((SELECT jsonb_agg(jsonb_build_object('name',u.name,'factor',u.factor,'price_paisa',u.price_paisa) ORDER BY factor,name) FROM units u WHERE u.medicine_id=m.id),'[]') FROM medicines m;
UPDATE medicines SET catalog_id=id;
ALTER TABLE medicines DROP CONSTRAINT medicines_barcode_key;
ALTER TABLE medicines ADD CONSTRAINT branch_barcode_unique UNIQUE(branch_id,barcode);
CREATE UNIQUE INDEX branch_catalog_unique ON medicines(branch_id,catalog_id) WHERE catalog_id IS NOT NULL;
CREATE TABLE stock_transfers(id uuid PRIMARY KEY,from_branch_id uuid NOT NULL REFERENCES branches,to_branch_id uuid NOT NULL REFERENCES branches,number text NOT NULL UNIQUE,idempotency_key uuid NOT NULL,request_hash text NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_branch_id<>to_branch_id),UNIQUE(from_branch_id,idempotency_key));
CREATE TABLE transfer_lines(id uuid PRIMARY KEY,transfer_id uuid NOT NULL REFERENCES stock_transfers,source_batch_id uuid NOT NULL REFERENCES batches,catalog_id uuid NOT NULL REFERENCES shared_products,medicine_name text NOT NULL,batch_code text NOT NULL,expiry date NOT NULL,quantity_base integer NOT NULL CHECK(quantity_base>0),cost_paisa bigint NOT NULL CHECK(cost_paisa>=0));
CREATE TABLE transfer_receipts(id uuid PRIMARY KEY,transfer_id uuid NOT NULL UNIQUE REFERENCES stock_transfers,branch_id uuid NOT NULL REFERENCES branches,request_hash text NOT NULL,actor_id uuid NOT NULL REFERENCES users,disposition text NOT NULL CHECK(disposition IN ('AVAILABLE','QUARANTINED')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE batches ALTER COLUMN purchase_id DROP NOT NULL;
ALTER TABLE batches ADD COLUMN transfer_line_id uuid REFERENCES transfer_lines;
ALTER TABLE batches ADD COLUMN source_batch_id uuid REFERENCES batches;
ALTER TABLE batches ADD CONSTRAINT batch_origin_required CHECK(purchase_id IS NOT NULL OR transfer_line_id IS NOT NULL OR source_batch_id IS NOT NULL);
CREATE TABLE transfer_receipt_lines(id uuid PRIMARY KEY,receipt_id uuid NOT NULL REFERENCES transfer_receipts,line_id uuid NOT NULL UNIQUE REFERENCES transfer_lines,destination_batch_id uuid NOT NULL UNIQUE REFERENCES batches,quantity_base integer NOT NULL CHECK(quantity_base>0));
ALTER TABLE movements DROP CONSTRAINT movements_type_check;
ALTER TABLE movements ADD CONSTRAINT movements_type_check CHECK(type IN ('RECEIPT','SALE','RETURN_QUARANTINE','COUNT_ADJUSTMENT','WRITE_OFF','TRANSFER_OUT','TRANSFER_IN'));
ALTER TABLE movements ADD COLUMN unit_cost_paisa bigint;
CREATE FUNCTION movement_cost_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN SELECT cost_paisa INTO NEW.unit_cost_paisa FROM batches WHERE id=NEW.batch_id;RETURN NEW; END $$;
CREATE TRIGGER movement_cost BEFORE INSERT ON movements FOR EACH ROW EXECUTE FUNCTION movement_cost_snapshot();
CREATE TABLE accounts(code text PRIMARY KEY,name text NOT NULL,type text NOT NULL CHECK(type IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')),active boolean NOT NULL DEFAULT true);
INSERT INTO accounts(code,name,type) VALUES('1000','Cash','ASSET'),('1010','Card clearing','ASSET'),('1020','Wallet clearing','ASSET'),('1030','Bank','ASSET'),('1100','Customer receivables','ASSET'),('1200','Inventory at cost','ASSET'),('1300','Inventory in transit','ASSET'),('1400','Interbranch receivable','ASSET'),('2000','Supplier payables','LIABILITY'),('2100','Output tax','LIABILITY'),('2400','Interbranch payable','LIABILITY'),('3000','Opening equity','EQUITY'),('4000','Sales revenue','REVENUE'),('4010','Sales returns','REVENUE'),('5000','Cost of goods sold','EXPENSE'),('5100','Stock loss','EXPENSE'),('6000','Operating expenses','EXPENSE'),('7000','Inventory adjustment gain','REVENUE');
CREATE TABLE journals(id uuid PRIMARY KEY,branch_id uuid NOT NULL REFERENCES branches,posting_date date NOT NULL,description text NOT NULL,source_type text NOT NULL,source_id uuid NOT NULL,request_hash text NOT NULL,actor_id uuid NOT NULL REFERENCES users,reverses_id uuid UNIQUE REFERENCES journals,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(branch_id,source_type,source_id));
CREATE TABLE journal_lines(id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journals,account_code text NOT NULL REFERENCES accounts,debit_paisa bigint NOT NULL DEFAULT 0 CHECK(debit_paisa>=0),credit_paisa bigint NOT NULL DEFAULT 0 CHECK(credit_paisa>=0),CHECK((debit_paisa>0 AND credit_paisa=0) OR (credit_paisa>0 AND debit_paisa=0)));
CREATE FUNCTION validate_balanced_journal() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j uuid; n bigint; balance numeric; BEGIN IF TG_TABLE_NAME='journals' THEN j:=NEW.id; ELSE j:=NEW.journal_id; END IF; SELECT count(*),COALESCE(sum(debit_paisa-credit_paisa),0) INTO n,balance FROM journal_lines WHERE journal_id=j;IF n<2 OR balance<>0 THEN RAISE EXCEPTION 'Journal requires two or more balanced entries';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER journal_balanced AFTER INSERT ON journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_balanced_journal();
CREATE CONSTRAINT TRIGGER journal_line_balanced AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_balanced_journal();
CREATE INDEX journals_branch_date ON journals(branch_id,posting_date);
CREATE TABLE connector_profiles(branch_id uuid PRIMARY KEY REFERENCES branches,provider_name text NOT NULL DEFAULT '',documentation_ref text NOT NULL DEFAULT '',mode text NOT NULL DEFAULT 'UNCONFIGURED' CHECK(mode IN ('UNCONFIGURED','EXPORT_ONLY')),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE connector_exports(id uuid PRIMARY KEY,branch_id uuid NOT NULL REFERENCES branches,from_date date NOT NULL,to_date date NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX transfers_destination ON stock_transfers(to_branch_id,created_at);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['stock_transfers','transfer_lines','transfer_receipts','transfer_receipt_lines','journals','journal_lines','connector_exports'] LOOP EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION deny_history_change()',t); END LOOP; END $$;
